[Form]
public class AVATurnoverAlliance extends FormRun
{
    NDXSalesNoteCustomer nDXSalesNoteCustomer;
    QueryBuildRange      qbrCustTable;

}

public void init()
{
    nDXSalesNoteCustomer = NDXSalesNoteCustomer::construct();
    super();

    DeterminationDate.dateValue(nDXSalesNoteCustomer.parmSalesDate());
}

private void getData()
{
    NDXSNSalesItemGroupCustomerTmp lNDX_SNSalesItemGroupCustomerTmp;
    NDXAllianceTreeCustomer lNDXAllianceTreeCustomer;

    //Check if some data exists NDXAllianceTreeCustomer
    select count(RecId) from lNDXAllianceTreeCustomer;

    if(lNDXAllianceTreeCustomer.RecId == 0)
    {
        throw error("@NDX:NDXAllianceTreeCustomerNoData");
    }

    nDXSalesNoteCustomer.getSales(NDXSNAlliance);

    NDXSalesNoteCustomerTmp_jeDatensatz.setTmpData(nDXSalesNoteCustomer.nDX_SalesNoteCustomerTmp);
    NDXSalesNoteCustomerTmp_jeDatensatz_DS.research();

    NDXSalesNoteCustomerTmp_alleFirmen.setTmpData(nDXSalesNoteCustomer.nDX_SalesNoteCustomerTmp);
    NDXSalesNoteCustomerTmp_alleFirmen_DS.executeQuery();

    NDXSalesNoteCustomerTmp_jeFirma.setTmpData(nDXSalesNoteCustomer.nDX_SalesNoteCustomerTmp);
    NDXSalesNoteCustomerTmp_jeFirma_DS.executeQuery();

    NDXSalesNoteCustomerTmp_perCustomer.setTmpData(nDXSalesNoteCustomer.nDX_SalesNoteCustomerTmp);
    NDXSalesNoteCustomerTmp_perCustomer_DS.executeQuery();

    NDXSalesNoteCustomerTmp_perCustomerGroup.setTmpData(nDXSalesNoteCustomer.nDX_SalesNoteCustomerTmp);
    NDXSalesNoteCustomerTmp_perCustomerGroup_DS.executeQuery();

    NDXSalesNoteItemGroupTmp_jeDatensatz.setTmpData(nDXSalesNoteCustomer.nDX_SalesNoteItemGroupTmp);
    NDXSalesNoteItemGroupTmp_jeDatensatz_DS.executeQuery();

    NDXSalesNoteItemGroupTmp_jeFirma.setTmpData(nDXSalesNoteCustomer.nDX_SalesNoteItemGroupTmp);
    NDXSalesNoteItemGroupTmp_jeFirma_DS.executeQuery();

    //Sales Volume
    lNDX_SNSalesItemGroupCustomerTmp = nDXSalesNoteCustomer.getSalesCustomerItemGrp(CustTable.AccountNum);

    NDXSNSalesItemGroupCustomerTmp.setTmpData(lNDX_SNSalesItemGroupCustomerTmp);
    NDXSNSalesItemGroupCustomerTmp_DS.executeQuery();

    NDXSNSalesItemGroupCustomerTmp_jeFirma.setTmpData(lNDX_SNSalesItemGroupCustomerTmp);
    NDXSNSalesItemGroupCustomerTmp_jeFirma_DS.executeQuery();

    NDXSNSalesItemGroupCustomerTmp_jeFirmaAktiv.setTmpData(lNDX_SNSalesItemGroupCustomerTmp);
    NDXSNSalesItemGroupCustomerTmp_jeFirmaAktiv_DS.executeQuery();

    NDXSNSalesItemGroupCustomerTmp_Aktiv.setTmpData(lNDX_SNSalesItemGroupCustomerTmp);
    NDXSNSalesItemGroupCustomerTmp_Aktiv_DS.executeQuery();

    NDXSNItemGroupDeactiveTmp.setTmpData(nDXSalesNoteCustomer.nDX_SNItemGroupDeactiveTmp);
    NDXSNItemGroupDeactiveTmp_DS.executeQuery();

    NDXSNClientDeactiveTmp.setTmpData(nDXSalesNoteCustomer.nDX_SNClientDeactiveTmp);
    NDXSNClientDeactiveTmp_DS.executeQuery();

    element.checkDiff();
}

void checkDiff()
{
    const str CR = '\n';

    NDXSalesNoteCustomerTmp            nDX_SalesNoteCustomerTmpReturn;
    NDXSNClientDeactiveTmp             nDX_SNClientDeactiveTmp;
    NDXSNItemGroupDeactiveTmp          nDX_SNItemGroupDeactiveTmp;
    Counter countDiffs;
    boolean lHasDiffs;
    str infoTxt;

    nDX_SalesNoteCustomerTmpReturn  = NDXSalesNoteCustomer::checkAmountDiff1(NDXSalesNoteCustomerTmp_jeFirma, NDXSalesNoteItemGroupTmp_jeFirma);

    select count(RecId) from nDX_SalesNoteCustomerTmpReturn;

    countDiffs = int642int(nDX_SalesNoteCustomerTmpReturn.RecId);
    lHasDiffs   = lHasDiffs || countDiffs;

    if (countDiffs)
    {
        Warning(   strfmt("@NDX:NDXSalesVolumeInfo", countDiffs));        // Zwischen "Debitoren-Umsatz (Summen je Firma)" und "Artikelgruppen-Umsatz (Summen je Firma)" wurden [%1] Differenzen erkannt.
        infoTxt += strfmt("@NDX:NDXSalesVolumeInfo", countDiffs) + CR;
        while select nDX_SalesNoteCustomerTmpReturn
        {
            Warning(   strfmt("@NDX:NDXSalesVolumeInfo2", nDX_SalesNoteCustomerTmpReturn.Company, nDX_SalesNoteCustomerTmpReturn.SalesAmount));  // Firma [%1] Differenz [%2]
            infoTxt += strfmt("@NDX:NDXSalesVolumeInfo2", nDX_SalesNoteCustomerTmpReturn.Company, nDX_SalesNoteCustomerTmpReturn.SalesAmount) + CR;
        }
    }

    nDX_SalesNoteCustomerTmpReturn  = NDXSalesNoteCustomer::checkAmountDiff2(NDXSalesNoteCustomerTmp_jeFirma, NDXSNSalesItemGroupCustomerTmp_jeFirma);

    select count(RecId) from nDX_SalesNoteCustomerTmpReturn;

    countDiffs = int642int(nDX_SalesNoteCustomerTmpReturn.RecId);
    lHasDiffs   = lHasDiffs || countDiffs;

    if (countDiffs)
    {
        Warning(   strfmt("@NDX:NDXSalesVolumeInfo3", countDiffs));            // Zwischen "Debitoren-Umsatz (Summen je Firma)" und "Umsatzmeldung an Kunde" wurden [%1] Differenzen erkannt.
        infoTxt += strfmt("@NDX:NDXSalesVolumeInfo3", countDiffs) + CR;
        while select nDX_SalesNoteCustomerTmpReturn
        {
            Warning(   strfmt("@NDX:NDXSalesVolumeInfo2", nDX_SalesNoteCustomerTmpReturn.Company, nDX_SalesNoteCustomerTmpReturn.SalesAmount)); // Firma [%1] Differenz [%2]
            infoTxt += strfmt("@NDX:NDXSalesVolumeInfo2", nDX_SalesNoteCustomerTmpReturn.Company, nDX_SalesNoteCustomerTmpReturn.SalesAmount) + CR;
        }
    }

    nDX_SalesNoteCustomerTmpReturn  = NDXSalesNoteCustomer::checkAmountDiff3(NDXSNSalesItemGroupCustomerTmp_jeFirma, NDXSNSalesItemGroupCustomerTmp_jeFirmaAktiv);

    select count(RecId) from nDX_SalesNoteCustomerTmpReturn;

    countDiffs = int642int(nDX_SalesNoteCustomerTmpReturn.RecId);
    lHasDiffs   = lHasDiffs || countDiffs;

    if (countDiffs)
    {
        Warning(   strfmt("@NDX:NDXSalesVolumeInfo4", countDiffs));            // Zwischen "Umsatzmeldung an Kunde" und "Umsatzmeldung an Kunde (Aktiv)" wurden [%1] Differenzen erkannt.
        infoTxt += strfmt("@NDX:NDXSalesVolumeInfo4", countDiffs) + CR;
        while select nDX_SalesNoteCustomerTmpReturn
        {
            Warning(   strfmt("@NDX:NDXSalesVolumeInfo2", nDX_SalesNoteCustomerTmpReturn.Company, nDX_SalesNoteCustomerTmpReturn.SalesAmount));  // Firma [%1] Differenz [%2]
            infoTxt += strfmt("@NDX:NDXSalesVolumeInfo2", nDX_SalesNoteCustomerTmpReturn.Company, nDX_SalesNoteCustomerTmpReturn.SalesAmount) + CR;
        }
    }

    nDX_SNClientDeactiveTmp.setTmpData(nDXSalesNoteCustomer.nDX_SNClientDeactiveTmp);
    select count(RecId) from nDX_SNClientDeactiveTmp;
    if (nDX_SNClientDeactiveTmp.RecId)
    {
        Warning(   strfmt("@NDX:NDXSalesVolumeInfo5", nDX_SNClientDeactiveTmp.RecId));
        infoTxt += strfmt("@NDX:NDXSalesVolumeInfo5", nDX_SNClientDeactiveTmp.RecId) + CR;     // [%1] Debitoren-Umsätze werden nicht gemeldet.
    }

    nDX_SNItemGroupDeactiveTmp.setTmpData(nDXSalesNoteCustomer.nDX_SNItemGroupDeactiveTmp);
    select count(RecId) from nDX_SNItemGroupDeactiveTmp;
    if (nDX_SNItemGroupDeactiveTmp.RecId)
    {
        Warning(   strfmt("@NDX:NDXSalesVolumeInfo6", nDX_SNItemGroupDeactiveTmp.RecId));
        infoTxt += strfmt("@NDX:NDXSalesVolumeInfo6", nDX_SNItemGroupDeactiveTmp.RecId) + CR;      // [%1] Artikelgruppen-Umsätze werden nicht gemeldet.
    }

    strNote.text(infoTxt);
}

void clearData()
{
    NDXSalesNoteCustomerTmp        nDX_SalesNoteCustomerTmp;
    NDXSalesNoteItemGroupTmp       nDX_SalesNoteItemGroupTmp;
    NDXSNSalesItemGroupCustomerTmp lNDX_SNSalesItemGroupCustomerTmp;

    NDXSalesNoteCustomerTmp_jeDatensatz.setTmpData(nDX_SalesNoteCustomerTmp);
    NDXSalesNoteCustomerTmp_jeDatensatz_DS.executeQuery();

    NDXSalesNoteCustomerTmp_alleFirmen.setTmpData(nDX_SalesNoteCustomerTmp);
    NDXSalesNoteCustomerTmp_alleFirmen_DS.executeQuery();

    NDXSalesNoteCustomerTmp_jeFirma.setTmpData(nDX_SalesNoteCustomerTmp);
    NDXSalesNoteCustomerTmp_jeFirma_DS.executeQuery();

    NDXSalesNoteItemGroupTmp_jeDatensatz.setTmpData(nDX_SalesNoteItemGroupTmp);
    NDXSalesNoteItemGroupTmp_jeDatensatz_DS.executeQuery();

    NDXSalesNoteItemGroupTmp_jeFirma.setTmpData(nDX_SalesNoteItemGroupTmp);
    NDXSalesNoteItemGroupTmp_jeFirma_DS.executeQuery();

    NDXSNSalesItemGroupCustomerTmp.setTmpData(lNDX_SNSalesItemGroupCustomerTmp);
    NDXSNSalesItemGroupCustomerTmp_DS.executeQuery();

    NDXSNSalesItemGroupCustomerTmp_jeFirma.setTmpData(lNDX_SNSalesItemGroupCustomerTmp);
    NDXSNSalesItemGroupCustomerTmp_jeFirma_DS.executeQuery();

    NDXSNSalesItemGroupCustomerTmp_jeFirmaAktiv.setTmpData(lNDX_SNSalesItemGroupCustomerTmp);
    NDXSNSalesItemGroupCustomerTmp_jeFirmaAktiv_DS.executeQuery();

    NDXSNSalesItemGroupCustomerTmp_Aktiv.setTmpData(lNDX_SNSalesItemGroupCustomerTmp);
    NDXSNSalesItemGroupCustomerTmp_Aktiv_DS.executeQuery();

}

public int active()
{
    int ret;

    NDXSNAlliance_DS.reread();

    ret = super();

    element.clearData();

    return ret;
}

