public void init()
{
    Query   q;

    super();

    q = this.query();
    q.allowCrossCompany(true);
    q.addCompanyRange(NDXHelperCommon::NDXCompanys2CompanyId(NDXCompanyBE::Niedax));
    qbrCustTable = q.dataSourceName(this.name()).addRange(fieldnum(CustTable, AccountNum));
}

