public boolean modified()
{
    boolean ret;

    ret = super();

    if(nDXSalesNoteCustomer != null)
    {
        this.dateValue(nDXSalesNoteCustomer.parmSalesDate(this.dateValue()));
    }

    return ret;
}

public void clicked()
{
    //super();
    Args args = new Args();
    args.parmObject(NDXSNGenData::construct(nDXSalesNoteCustomer));

    new MenuFunction(menuItemActionStr(NDXSNSalesItemGroupCustomerTmpExport), MenuItemType::Action).run(args);
}
